import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_gemm(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <algorithm>

using namespace cute;

// Tile sizes for the cooperative shared-memory GEMM
constexpr int BM = 32;
constexpr int BN = 32;
constexpr int BK = 32;

// Split-K tiled GEMM kernel using CuTe tensors for indexing.
// Each block computes a BM x BN tile of C over a sub-range of K
// (assigned via blockIdx.z) and accumulates its partial result
// into global memory C using atomicAdd. C must be pre-zeroed.
__global__ void cute_gemm_splitk_kernel(
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K, int Ksplit)
{
    __shared__ float sA[2][BM][BK];
    __shared__ float sB[2][BK][BN];
    int tx = threadIdx.x; // 0..BN-1
    int ty = threadIdx.y; // 0..BM-1
    int row = blockIdx.y * BM + ty;
    int col = blockIdx.x * BN + tx;
    int kStart = blockIdx.z * Ksplit;
    int kEnd   = min(kStart + Ksplit, K);
    // CuTe tensors over global memory (row-major layouts)
    Tensor gA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));
    Tensor gB = make_tensor(make_gmem_ptr(B), make_shape(K, N), make_stride(N, Int<1>{}));
    float acc = 0.f;
    // Loads a BM x BK tile of A and a BK x BN tile of B (vectorized float4
    // where possible) into the given double-buffer slot 'buf'.
    auto load_tile = [&](int buf, int k0) {
        if ((tx & 3) == 0) {
            int kA = k0 + tx;
            if (row < M && (kA + 3) < K) {
                float4 v = *reinterpret_cast<const float4*>(&A[row * K + kA]);
                sA[buf][ty][tx + 0] = v.x;
                sA[buf][ty][tx + 1] = v.y;
                sA[buf][ty][tx + 2] = v.z;
                sA[buf][ty][tx + 3] = v.w;
            } else {
                #pragma unroll
                for (int i = 0; i < 4; ++i) {
                    int kAi = kA + i;
                    sA[buf][ty][tx + i] = (row < M && kAi < K) ? gA(row, kAi) : 0.f;
                }
            }
            int kB = k0 + ty;
            if (kB < K && (col + 3) < N) {
                float4 v = *reinterpret_cast<const float4*>(&B[kB * N + col]);
                sB[buf][ty][tx + 0] = v.x;
                sB[buf][ty][tx + 1] = v.y;
                sB[buf][ty][tx + 2] = v.z;
                sB[buf][ty][tx + 3] = v.w;
            } else {
                #pragma unroll
                for (int i = 0; i < 4; ++i) {
                    int coli = col + i;
                    sB[buf][ty][tx + i] = (kB < K && coli < N) ? gB(kB, coli) : 0.f;
                }
            }
        }
    };
    // Software-pipelined (double-buffered) main loop: prefetch the next
    // K-tile into the alternate shared-memory buffer while consuming the
    // currently loaded tile for the FMA accumulation. This overlaps global
    // memory latency with compute and reduces the per-iteration barrier
    // count from two __syncthreads() calls down to one.
    if (kStart < kEnd) {
        load_tile(0, kStart);
    }
    __syncthreads();
    int cur = 0;
    for (int k0 = kStart; k0 < kEnd; k0 += BK) {
        int nextK0 = k0 + BK;
        int next = cur ^ 1;
        bool hasNext = (nextK0 < kEnd);
        if (hasNext) {
            load_tile(next, nextK0);
        }
        #pragma unroll
        for (int k = 0; k < BK; ++k) {
            acc += sA[cur][ty][k] * sB[cur][k][tx];
        }
        __syncthreads();
        cur = next;
    }
    if (row < M && col < N) {
        atomicAdd(&C[row * N + col], acc);
    }
}

torch::Tensor cute_gemm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");

    int M = (int)A.size(0);
    int K = (int)A.size(1);
    int N = (int)B.size(1);
    TORCH_CHECK((int)B.size(0) == K, "B.size(0) must equal A.size(1)");

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    auto C   = torch::zeros({M, N}, A.options());

    // Determine split-K factor: aim for enough blocks to saturate the GPU
    // while keeping each block's K-range a multiple of BK where possible.
    int totalKTiles = (K + BK - 1) / BK;
    int numKSplits  = std::min(128, totalKTiles);
    if (numKSplits < 1) numKSplits = 1;
    int kTilesPerSplit = (totalKTiles + numKSplits - 1) / numKSplits;
    int Ksplit = kTilesPerSplit * BK;

    dim3 block(BN, BM);
    dim3 grid((N + BN - 1) / BN,
               (M + BM - 1) / BM,
               (K + Ksplit - 1) / Ksplit);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_gemm_splitk_kernel<<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
        M, N, K, Ksplit);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE gemm launch failed");
    return C;
}
"""

cute_ext = load_inline(
    name="cute_gemm_splitk_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_gemm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B)
    with a large K dimension, implemented via a custom split-K CuTe GEMM
    kernel for improved GPU utilization when K is very large relative to
    M and N.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_gemm(A.cuda(), B.cuda())

